/* gen-exceptions: crdist-exceptions.h, the table of every binary32 input
   at which a function's fast path (crdist-fast.h) can't decide the
   rounding, with the correctly rounded result from MPFR (crdist-ref.c,
   kit_ref1). Every one of the 2^32 inputs of each function is tried.
     make crdist-exceptions   (a minute on 64 threads; mostly the 3 x 2^32 fast paths) */
#include <fenv.h>
#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include "kit.h"
#include "crdist-fast.h"
#include "crdist-ref.h"

static const kit_mpfr1 REF[CRDIST_NFN] = {crdist_mpfr_erfinv, crdist_mpfr_erfcinv, crdist_mpfr_probit, crdist_mpfr_ndtr,
                                             crdist_mpfr_log_ndtr, crdist_mpfr_normpdf, crdist_mpfr_logit};

static int cmp32(const void *a, const void *b) { uint32_t x = *(const uint32_t *)a, y = *(const uint32_t *)b; return x < y ? -1 : x > y; }

int main(void)
{
  printf("/* crdist-exceptions.h: generated by dist/gen-exceptions.c (make crdist-exceptions); do not edit.\n"
         "   Every binary32 input at which a fast path in crdist-fast.h can't decide\n"
         "   the rounding, with the correctly rounded result (MPFR), sorted by input bits. */\n");
  for (int f = 0; f < CRDIST_NFN; f++) {
    size_t cap = 1 << 16, n = 0; uint32_t *hard = malloc(cap * 4);
#pragma omp parallel
    {
      fesetenv(FE_DFL_ENV);
      size_t lc = 1024, ln = 0; uint32_t *loc = malloc(lc * 4);
#pragma omp for schedule(dynamic, 1 << 16)
      for (int64_t i = 0; i < (int64_t)1 << 32; i++) {
        uint32_t u = (uint32_t)i; float x, y; memcpy(&x, &u, 4);
        if (crdist_decide32(f, x, &y)) continue;
        if (ln == lc) loc = realloc(loc, (lc *= 2) * 4);
        loc[ln++] = u;
      }
#pragma omp critical
      {
        while (n + ln > cap) hard = realloc(hard, (cap *= 2) * 4);
        memcpy(hard + n, loc, ln * 4); n += ln;
      }
      free(loc);
    }
    qsort(hard, n, 4, cmp32);
    uint32_t *want = malloc((n ? n : 1) * 4);
#pragma omp parallel for schedule(dynamic, 1)
    for (size_t i = 0; i < n; i++) want[i] = (uint32_t)kit_ref1(KIT_B32, REF[f], hard[i], MPFR_RNDN);
    printf("static const uint32_t crdist_exc_%s[][2] = {", crdist_fn_name[f]);
    for (size_t i = 0; i < n; i++) printf("%s{0x%08xu, 0x%08xu}", !i ? "\n  " : i % 4 ? ", " : ",\n  ", hard[i], want[i]);
    printf("%s};\n", n ? "\n" : "{0, 0}");
    printf("#define CRDIST_EXC_N_%s %zu\n", crdist_fn_name[f], n);
    fprintf(stderr, "%-8s %zu inputs undecided by the fast path\n", crdist_fn_name[f], n);
    free(hard); free(want);
  }
  printf("static const struct { const uint32_t (*t)[2]; size_t n; } crdist_exc[] = {");
  for (int f = 0; f < CRDIST_NFN; f++) printf("%s{crdist_exc_%s, CRDIST_EXC_N_%s}", f % 2 ? ", " : "\n  ", crdist_fn_name[f], crdist_fn_name[f]);
  printf("};\n");
  if (crdist_ref_long) fprintf(stderr, "note: %lu comparisons needed more than 512 bits\n", crdist_ref_long);
  return 0;
}
